(window.webpackJsonp=window.webpackJsonp||[]).push([[3],{538:function(e,t,n){"use strict";n.r(t),t.default={meta:{siteName:"Sustainable Theater | NTCH",docDesc:"The NTCH is not only a “ venue for everyone to access to performing arts ” but also a platform for initiatives to respond to international trends simultaneously. We are delighted to continuously create an inclusive world for us all and also launch exchanges and debates among diversified cultures to respond to contemporary issues, put forward imagination for the future, and further practice all possibilities for sustainability.",docThumb:"",currentUrl:"",keyWords:"Sustainable Theater"},esg_link:"https://npac-ntch.org/zh",footer_text:"“A Theater for ALL”",video_title:"“ A Sustainable Theater,<br>A World for Us All  ”",top:{title:"A Theater for ALL",desc:"The NTCH is not only a “ venue for everyone to access to performing arts ” but also a platform for initiatives to respond to international trends simultaneously. We are delighted to continuously create an inclusive world for us all and also launch exchanges and debates among diversified cultures to respond to contemporary issues, put forward imagination for the future, and further practice all possibilities for sustainability."},menu:[{image:["img/public/n-1.jpg"],title:"Open Space",id:"space"},{image:["img/public/n-2.jpg"],title:"Embrace Diversity",id:"embrace"},{image:["img/public/n-3.jpg"],title:"Environmentally Friendly",id:"env"},{image:["img/public/n-4.jpg"],title:"Collaboration",id:"collaboration"},{image:["img/public/n-5.jpg"],title:"Plans for Carbon Reduction",id:"join"},{image:["img/public/n-6.jpg"],title:"Attentive Services",id:"service"},{image:["img/public/n-7.jpg"],title:"A Sustainable Theater,<br>A World for Us All",id:"future"}],space:{title:"“  We are dedicated to increasing the accessibility of venues, maintaining an organic space, and removing as many obstacles as possible that prevent people from going into the theater.  ”",subtitle:"Open Space",desc:"The main architecture of the NTCH was completed in 1987. With the diversified development of the society, more considerate and subtle concerns to different groups of population become essential. Therefore, in addition to general maintenance and repairs, we have also continuously thought about how we can break through the physical limitation and build a barrier-free space for all people. To this end, we underwent a large-scale renovation in 2016 to build barrier-free ramps and toilets and add more accessible seats. Furthermore, we completed the upgrading and renovation of the Performing Arts Library and re-organized more than 10,000 items of audio-video materials, publications, and out-of-print vinyl records in our collection. We also built a comfortable and spacious space for people to freely appreciate all kind of works and performances without having to purchase tickets or dress up so that they can enjoy themselves in the NTCH and make arts a part of their daily routines."},embrace:{title:"“  The foundation of cultural equality is to give everyone the right to freely appreciate and interpret arts.  ”",subtitle:"Embrace Diversity",sub_sub_title1:"Barrier-free Experience",desc1:"We believe neither physical nor mental disabilities are obstacles for participating in the theater. On the other hand, they may be able to create new perspectives for experiencing arts. As of 2023, the NTCH have developed 15 accessibility services for appreciating performances and guided tours, including audio description, touch tour, sign language interpreting, and removable armrest seatings, and also offered “Relaxed Performances” for highly sensitive audiences to enjoy arts in a low light and sound environment and timely stretch their bodies. Other than implementing the concepts within venues, we also attach great importance to education and promotion externally and have hosted over 1,000 promotional and experiencing events and assisted multiple performing arts groups in cultivating talents related to inclusive service.",link1_text:"→Learn more about accessibility services",link1_url:"https://npac-ntch.org/visits/general/accessibility?lang=en-US",sub_sub_title2:"Equal Right to Arts",desc2:"The NTCH embarked on the path of art equality in 2007, when it began to offer the opportunities for students in remote countryside, senior citizens, and less-privileged people to access theaters and also bring artists to campuses to provide students with tailor-made approaches to arts. It has since then brought people closer not only to arts but also to each other. Events such as parent-child workshops and elder-youth joint creations initiate dialogues and facilitate mutual understandings between different generations by sharing with each other their life experiences, warmth, and energy. It is our hope to continue reaching out and spreading seeds for arts along the way so that such inspiration and moving moments will find their way to take roots in the hearts of more people.",sub_sub_title3:"Gender Equality Initiative",desc3:"As the leading cultural brand in promoting diversity and inclusiveness in Taiwan, the NTCH expects itself to think out of box so as to take care of those minorities who need artistic shelter with ahead-of-the-times thinking and voice out for them with concrete actions.<br><br>Before the #MeToo movement became the rage, artist-in-residence Huang Yu-ching explored the sexual violence caused by imbalanced power in her work Man of the Theater. Before winning the championship, Nymphia participated in 2057: Rehearsing ways of living, a part of the project in celebration of the 35th anniversary of the NTCH’s founding. The NTCH also invited American performing artist Taylor Mac to redefine the mainstream history with an alternative gender perspective with the performance of Judy, a drag queen.<br><br>In the initiative of women’s rights, the 2023 NTCH artist-in-residence Lee Pin Yao  organized a series of exhibitions and events from the queer perspective to engage in close interactions with audiences and remodel gender-friendly toilets, aiming to facilitate reflections and vigilance. With only 30 percent of management jobs being held by women, the NTCH is dedicated to continuously deepening the development of women’s career and safeguarding a gender-friendly working environment."},env:{title:"“ Arts transcend time and space. We inherit historical cultures from the past, respond to contemporary issues with creativity now, and meanwhile ponder what kind of world to be left behind for human beings in the future. ”",subtitle:"Environmentally Friendly",sub_sub_title1:"Carbon-reduction Strategy",desc1:"It is our belief that the foundation to make right decisions and take right actions is to introduce the awareness of solid scientific methods and pragmatic data. The NTCH established a cross-departmental working group for sustainability and inclusiveness in 2018 and completed the 2022 ISO 140641-1:2018 greenhouse gas inventory for organizations in 2023, becoming the first theater venue to complete SGS verification in Taiwan. Targeting the largest carbon emission sources identified in the results of the inventory -- electric power cost throughout the year in the whole venue (75%), products such as marketing materials (14%), and transportation for visitors and business travels (7%) -- we put forward four major approaches to carbon reduction, including green procurement, energy saving, encouraging public transportation, and reducing printed materials. Only by starting with matters that are relatively easy to implement with less resistance can the pursuit of sustainability become a marathon and go on step by step.",link1_text:"→2025 Annual Report of NTCH",link1_url:"https://npac-www-file.npac-ntch.org/npac/upload/b1048f7801e8451d9e46d5209beaf432.pdf",sub_sub_title2:"Green Production",desc2:'In 2025,as the only member from Asia, the NTCH was invited to join the "Culture for the Planet" international alliance, and walk side by side on the path of sustainability with 32 cultural institutions from five continents, such as the Tate in the UK and the Bilbao Guggenheim Museum in Spain.<br><br>Green theater includes the collaboration with Europe’s STAGES (Sustainable Theatre Alliance for a Green Environmental Shift) in the Autumn Festival in 2023 for A Play for the Living in a Time of Extinction, which was the first mile for us to embark on the path of green production. In 2025, we calculated the carbon footprints of two programs: Sweet Tears by the Puppet & Its Double Theater at TIFA, and David Geselson\'s Everything You Always Wanted to See. We introduce green production procedures and sustainable and inclusive techniques into the system, and fully implement the "Sustainability Action Record Form" to provide sustainability guidelines that can be followed for rented, home-made, and co-produced programs. We expect the NTCH to be a model for green theaters and act as a driving force for the sustainable reforms of art and culture industries in Taiwan.',link2_text:"→Sidelights of NTCH Sustainable Theater Conference",link2_url:"https://pr.ntch.art/2025sidelights_web",sub_sub_title3:"Digital Transformation",desc3:"Sustainable practices require the carbon awareness among members in the organization and the effective carbon management by properly using the digitalized system. By optimizing the theater management system, we are able to streamline the administrative affairs in about 1,000 programs and reduce paper-based mail delivery and carbon emission caused by performing art groups’ travels to the venue. By promoting the digitalized systems for paper works and human resources to carry out cross-departmental integration, we further reduce cost for communication and waste of papers. In addition, we also expect audiences to respond to our initiatives and make more environmentally friendly choices, including the e-tickets offered by OPENTIX to reduce the waste of papers and the introduction of digital subscription of PAR-Performing Arts Redefined in 2022, which increased the online viewing by 65 percent. The NTCH gives full play to its influence within its capability and move toward the common goal of net-zero emission in 2050 set by Taiwan and the international community.",link3_text:"→2018-2025 NTCH Impact Report",link3_url:"https://npac-ntch.org/official-files/19fefdcd3ee0099185b4e8e1c1f2109c45881051.pdf",sub_sub_title4:"Sustainable Governance",desc4:"If you want to go fast, go alone, but if you want to go far, go together. – This African proverb properly conveys the mindset of the NTCH in promoting sustainable policies internally. We hosted sustainable consensus camps and encourage our staff to find problems and put forward solutions by drawing on collective wisdom. Staff from all departments, regardless their seniority or ranking, can freely express their thoughts in this channel of direct communication. In addition, we also host annual sustainable conference on a regular basis to seek differences among commonalities by sharing and meanwhile seek commonalities among differences through discussions. In such a process, we manage to understand each other’s positions and difficulties and try to work out the most commonly acceptable approach to achieving our goals. By means of team building, we walk forward in a unified pace on the path of sustainable practices."},collaboration:{title:"“ With the participation of our partners, we are more determined to move toward the goals. We will continue to connect energies from all sectors to improve the industrial sustainable ecology and supply chain. ”",subtitle:"Collaboration",sub_sub_title1:"Partners for Sustainability",data_text:"Data are based on the statistics in 2025",number:"24",unit:"A total of",after_unut:"enterprises partnered with <br>NTCH in sustainable concepts",data:[{title:"Art and Cultural Industry",list:[{content:"Number of events initiated by the venue and performing groups",number:"140",id:"count-1",unit:"+"},{content:'Promotion of e-tickets in OPENTEX<br><span class="note">*E-tickets are available for 56% of programs</span>',number:"10000",id:"count-2",unit:"+"},{content:"Number of domestic recipients of inclusive services",number:"29511",id:"count-3",unit:"+"}]},{title:"Audiences",list:[{content:"Number of programs",number:"720",id:"count-4",unit:"+"},{content:"Number of performances",number:"1087",id:"count-5",unit:"+"},{content:"Total number of audiences",number:"698461",id:"count-6",unit:"+"},{content:"Number of participants in art and cultural promotional events",number:"140262",id:"count-7",unit:"+"},{content:"Number of participants in cultural accessibility and promotion events",number:"145272",id:"count-8",unit:"+"},{content:"Number of NTCH members",number:"24815",id:"count-9",unit:"+"},{content:"Ratio of NTCH<br>e-membership card holders",number:"88",id:"count-10",unit:"%"},{content:'Growth rate of e-tickets<br><span class="note">*From 2021 to now, a total of 3,067,775 e-tickets have been issued, equivalent to reducing 16,000 kilogram carbon emission.</span><br><span class="note">In 2025, the total carbon reduction from electronic tickets accumulated to 5,206 kg CO₂e.</span>',number:"5",id:"count-11",unit:"%",highlight:!0}]},{title:"Staff",link:!0,list:[{content:"Number of participants in sustainable education and training programs",number:"2549",id:"count-12",unit:"+"}]}],collaboration:[{title:"金像電子",image:["img/public/2026-logo/03-金像電子.png"]},{title:"鈊象電子",image:["img/public/2026-logo/04-鈊象電子.png"]},{title:"財團法人力晶文化基金會",image:["img/public/2026-logo/06-財團法人力晶文化基金會-11.png"]},{title:"川流文教基金會",image:["img/public/2026-logo/08-川流文教基金會-11.png"]},{title:"中華電信股份有限公司",image:["img/public/2026-logo/10-中華電信股份有限公司-11.png"]},{title:"日月光半導體製造股份有限公司",image:["img/public/2026-logo/11-日月光半導體製造股份有限公司-11.png"]},{title:"日月光文教基金會",image:["img/public/2026-logo/12-日月光文教基金會-11.png"]},{title:"台塑石化股份有限公司",image:["img/public/2026-logo/13-台塑石化股份有限公司-11.png"]},{title:"台塑石油",image:["img/public/2026-logo/14-台塑石油-12.png"]},{title:"台新新光金控",image:["img/public/2026-logo/15-台新新光金控-11.png"]},{title:"財團法人玉山文教基金會",image:["img/public/2026-logo/16-財團法人玉山文教基金會-11.png"]},{title:"余紀忠文教基金會",image:["img/public/2026-logo/17-余紀忠文教基金會-111.png"]},{title:"金寶電子工業股份有限公司",image:["img/public/2026-logo/18-金寶電子工業股份有限公司-11.png"]},{title:"財團法人勇源教育發展基金會",image:["img/public/2026-logo/19-財團法人勇源教育發展基金會-12.png"]},{title:"凱基文化藝術基金會",image:["img/public/2026-logo/20-凱基文化藝術基金會-11.png"]},{title:"財團法人中華開發文教基金會",image:["img/public/2026-logo/21-財團法人中華開發文教基金會-11.png"]},{title:"凱基銀行",image:["img/public/2026-logo/22-凱基銀行-11.png"]},{title:"凱基人壽",image:["img/public/2026-logo/23-凱基人壽-11.png"]},{title:"張榮發基金會",image:["img/public/2026-logo/24-張榮發基金會_230420-02-1.png"]},{title:"國泰人壽保險股份有限公司",image:["img/public/2026-logo/25-國泰人壽保險股份有限公司-11.png"]},{title:"統一綜合證券股份有限公司",image:["img/public/2026-logo/26-統一綜合證券股份有限公司-11.png"]},{title:"財團法人聚陽文教基金會",image:["img/public/2026-logo/27-財團法人聚陽文教基金會-11.png"]},{title:"臺灣集中保管結算所",image:["img/public/2026-logo/28-臺灣集中保管結算所-11.png"]},{title:"財團法人中華民國證券櫃檯買賣中心",image:["img/public/2026-logo/29-財團法人中華民國證券櫃檯買賣中心-11.png"]}]},join:{title:"Know more about the Plans for Carbon Reduction",desc:'In 2026, we invite you to participate in the OPENTIX " Green Starlight Program" and practice carbon reduction actions by using electronic tickets!',join:[{image:["img/public/join_icon_03.png"],title:"Purchase E-tickets",button_text:"Green Starlight Plan→",link:"https://otgreenstar.opentix.life"}],subtitle:"Join Together",join2:[{title:"Programs with reading accessibility→",link:"ttps://npac-ntch.org/discover/learning?lang=en-US"},{title:"Fill in sustainable transportation questionnaire→",link:"https://docs.google.com/forms/d/e/1FAIpQLSfW4A6JW9_wh5NnsDHGBW8JOLUlYQ8LIeCeICuBof2ZpN6BFA/viewform"},{title:"Support the NTCH→",link:"https://npac-ntch.org/supports?lang=en-US"}]},service:{title:"Attentive Services",service:[{image:["img/public/icon_dog.png"],list:[{title:"Program with inclusive service→",link:"https://npac-ntch.org/media-center/media-news/10062?open-global-program-calendar=true&lang=en-US"},{title:"Accessibility Service →",link:"https://npac-ntch.org/visits/general/accessibility?lang=en-US"},{title:"KidsPlay - Childcare Services for NTCH Audience Members→",link:"https://npac-ntch.org/visits/general/childcare?lang=en-US"}]},{image:["img/public/icon_blind.png"],list:[{title:"Easy-read guide→",link:"https://npac-ntch.org/discover/events/8529-%E6%98%93%E8%AE%80%E5%B0%8E%E8%A6%BD?lang=en-US"},{title:"Touch tour→",link:"https://npac-ntch.org/discover/events/8525-%E8%A7%B8%E8%A6%BA%E5%B0%8E%E8%A6%BD?lang=en-US"},{title:"Sign-language tour→",link:"https://npac-ntch.org/discover/events/8527-%E6%89%8B%E8%AA%9E%E5%B0%8E%E8%A6%BD?lang=en-US"}]},{image:["img/public/icon_book.png"],list:[{title:"Download easy-read guidebook→",link:"https://npac-ntch.org/discover/learning?fbclid=IwZXh0bgNhZW0CMTAAAR1w3y1d_OnvZKgVC_UaJ8Ahu6NM47Dr8r_aPmHmQHEZRyUffZpbaGhP4R8_aem_6n3t2_7a7aMtgDy1EchxUw?lang=en-US"},{title:"Collect Braille guidebook→",link:"https://npac-ntch.org/discover/events/4181-%E5%B0%8E%E8%A6%BD%E9%BB%9E%E5%AD%97%E6%89%8B%E5%86%8A?lang=en-US"},{title:"More inclusive activities→",link:"https://npac-ntch.org/discover/events?lang=en-US"}]}]}}}}]);